// The REUSE tags the generated file carries, each spelt in two, so that
// REUSE does not read them as this file's own.
const (
	spdxLicence   = "SPDX-" + "License-Identifier: "
	spdxCopyright = "SPDX-" + "FileCopyrightText: "
)

// iscPart and mitPart are a package licence laid out as lucide-static's
// is, line for line, with example holders and list: the ISC License, then
// the icons derived from Feather and the MIT License they come under.
const (
	iscPart = `ISC License

Copyright (c) 2026 Example Icons and Contributors

Permission to use, copy, modify, and/or distribute this software for any
purpose with or without fee is hereby granted, provided that the above
copyright notice and this permission notice appear in all copies.

THE SOFTWARE IS PROVIDED "AS IS" AND THE AUTHOR DISCLAIMS ALL WARRANTIES
WITH REGARD TO THIS SOFTWARE INCLUDING ALL IMPLIED WARRANTIES OF
MERCHANTABILITY AND FITNESS. IN NO EVENT SHALL THE AUTHOR BE LIABLE FOR
ANY SPECIAL, DIRECT, INDIRECT, OR CONSEQUENTIAL DAMAGES OR ANY DAMAGES
WHATSOEVER RESULTING FROM LOSS OF USE, DATA OR PROFITS, WHETHER IN AN
ACTION OF CONTRACT, NEGLIGENCE OR OTHER TORTIOUS ACTION, ARISING OUT OF
OR IN CONNECTION WITH THE USE OR PERFORMANCE OF THIS SOFTWARE.
`
	mitPart = `
---

The following Lucide icons are derived from the Feather project:

airplay, moon, x

The MIT License (MIT) (for the icons listed above)

Copyright (c) 2013-present Example Author

Permission is hereby granted, free of charge, to any person obtaining a copy
of this software and associated documentation files (the "Software"), to deal
in the Software without restriction, including without limitation the rights
to use, copy, modify, merge, publish, distribute, sublicense, and/or sell
copies of the Software, and to permit persons to whom the Software is
furnished to do so, subject to the following conditions:

The above copyright notice and this permission notice shall be included in all
copies or substantial portions of the Software.

THE SOFTWARE IS PROVIDED "AS IS", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR
IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY,
FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE
AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER
LIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM,
OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE
SOFTWARE.
`
	licence = iscPart + mitPart
)

// svg returns an icon file as lucide-static writes one, with body inside
// its svg element.
func svg(name, body string) string {
	return `<!-- @license lucide-static v0.0.0 - ISC -->
<svg
  class="lucide lucide-` + name + `"
  xmlns="http://www.w3.org/2000/svg"
  width="24"
  height="24"
  viewBox="0 0 24 24"
  fill="none"
  stroke="currentColor"
  stroke-width="2"
  stroke-linecap="round"
  stroke-linejoin="round"
>
` + body + `
</svg>
`
}

// The SVG element every icon opens with, as genicons writes it.
const open = `<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" ` +
	`stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">`

// pkg returns a lucide-static package holding licence and the icons, by
// name.
func pkg(licence string, icons map[string]string) fstest.MapFS {
	fsys := fstest.MapFS{"LICENSE": {Data: []byte(licence)}, "package.json": {Data: []byte(`{"name":"lucide-static"}`)}}
	for name, data := range icons {
		fsys["icons/"+name+".svg"] = &fstest.MapFile{Data: []byte(data)}
	}
	return fsys
}

// fixture is a package with a sun, a moon and a monitor, the moon derived
// from Feather.
func fixture() fstest.MapFS {
	return pkg(licence, map[string]string{
		"sun":     svg("sun", "  <circle cx=\"12\" cy=\"12\" r=\"4\" />\n  <path d=\"M12 2v2\" />"),
		"moon":    svg("moon", `  <path d="M20.985 12.486a9 9 0 1 1-9.473-9.472" />`),
		"monitor": svg("monitor", "  <rect width=\"20\" height=\"14\" x=\"2\" y=\"3\" rx=\"2\" />\n  <line x1=\"8\" x2=\"16\" y1=\"21\" y2=\"21\" />"),
	})
}

func TestRenderWritesEachIcon(t *testing.T) {
	t.Parallel()

	out, err := icongen.Render(t.Context(), fixture(), []string{"sun", "moon", "monitor"})
	if err != nil {
		t.Fatalf("render: %v", err)
	}
	src := string(out)
	if !strings.HasPrefix(src, "// Code generated by cmd/genicons from lucide-static. DO NOT EDIT.\n") {
		t.Errorf("the file does not start with Go's generated-code line:\n%s", src)
	}
	if _, err := parser.ParseFile(token.NewFileSet(), "icons.go", out, parser.ParseComments); err != nil {
		t.Fatalf("the file is not Go: %v\n%s", err, src)
	}
	if formatted, err := format.Source(out); err != nil || !bytes.Equal(formatted, out) {
		t.Errorf("the file is not gofmt'd (%v)", err)
	}
	for _, want := range []string{
		"package icons\n",
		"func Sun() Icon {\n\treturn Icon{svg: `" + open + `<circle cx="12" cy="12" r="4"/><path d="M12 2v2"/></svg>` + "`}\n}",
		"func Moon() Icon {\n\treturn Icon{svg: `" + open + `<path d="M20.985 12.486a9 9 0 1 1-9.473-9.472"/></svg>` + "`}\n}",
		"func Monitor() Icon {\n\treturn Icon{svg: `" + open +
			`<rect width="20" height="14" x="2" y="3" rx="2"/><line x1="8" x2="16" y1="21" y2="21"/></svg>` + "`}\n}",
	} {
		if !strings.Contains(src, want) {
			t.Errorf("the file lacks\n%s\nin:\n%s", want, src)
		}
	}
	for _, unwanted := range []string{"class=", "@license", "lucide-sun"} {
		if strings.Contains(src, unwanted) {
			t.Errorf("the file keeps %q from the package's files:\n%s", unwanted, src)
		}
	}
}

func TestRenderMarksTheLicences(t *testing.T) {
	t.Parallel()

	header := func(t *testing.T, names ...string) string {
		t.Helper()
		out, err := icongen.Render(t.Context(), fixture(), names)
		if err != nil {
			t.Fatalf("icongen.Render(%v): %v", names, err)
		}
		head, _, ok := strings.Cut(string(out), "package icons")
		if !ok {
			t.Fatalf("no package clause in:\n%s", out)
		}
		return head
	}

	t.Run("an icon derived from Feather adds MIT", func(t *testing.T) {
		t.Parallel()

		got := header(t, "sun", "moon")
		for _, want := range []string{
			"// " + spdxLicence + "AGPL-3.0-only AND ISC AND MIT\n",
			"// " + spdxCopyright + "2026 Aryan Ameri <github@aryan.ameri.coffee>\n",
			"// " + spdxCopyright + "2026 Example Icons and Contributors\n",
			"// " + spdxCopyright + "2013-present Example Author\n",
		} {
			if !strings.Contains(got, want) {
				t.Errorf("the header lacks %q:\n%s", want, got)
			}
		}
	})

	t.Run("none derived from Feather, ISC alone", func(t *testing.T) {
		t.Parallel()

		got := header(t, "sun", "monitor")
		if !strings.Contains(got, "// "+spdxLicence+"AGPL-3.0-only AND ISC\n") {
			t.Errorf("the header does not mark AGPL-3.0-only AND ISC:\n%s", got)
		}
		for _, unwanted := range []string{"MIT", "Example Author"} {
			if strings.Contains(got, unwanted) {
				t.Errorf("the header names %q, which no icon it holds needs:\n%s", unwanted, got)
			}
		}
	})
}

func TestRenderIsDeterministic(t *testing.T) {
	t.Parallel()

	first, err := icongen.Render(t.Context(), fixture(), []string{"sun", "moon", "monitor"})
	if err != nil {
		t.Fatal(err)
	}
	for range 3 {
		again, err := icongen.Render(t.Context(), fixture(), []string{"monitor", "sun", "moon"})
		if err != nil {
			t.Fatal(err)
		}
		if !bytes.Equal(first, again) {
			t.Fatalf("render gave two different files for one package:\n%s\n----\n%s", first, again)
		}
	}
}

func TestRenderRefuses(t *testing.T) {
	t.Parallel()

	withSun := func(sun string) fstest.MapFS {
		return pkg(licence, map[string]string{"sun": sun})
	}
	// withLicence is a package with text as its LICENSE, and a well-formed
	// sun and moon.
	withLicence := func(text string) fstest.MapFS {
		return pkg(text, map[string]string{"sun": svg("sun", `<path d="M1 1" />`), "moon": svg("moon", `<path d="M1 1" />`)})
	}
	tests := []struct {
		name string
		fsys fstest.MapFS
		icon string
	}{
		{name: "a script element", fsys: withSun(svg("sun", `<script>alert(1)</script>`)), icon: "sun"},
		{name: "an element Lucide does not use", fsys: withSun(svg("sun", `<image href="x.png" />`)), icon: "sun"},
		{name: "an empty script element", fsys: withSun(svg("sun", `<script />`)), icon: "sun"},
		{name: "an empty group", fsys: withSun(svg("sun", `<g />`)), icon: "sun"},
		{name: "an event handler", fsys: withSun(svg("sun", `<path d="M1 1" onclick="alert(1)" />`)), icon: "sun"},
		{name: "a style attribute", fsys: withSun(svg("sun", `<path d="M1 1" style="fill:red" />`)), icon: "sun"},
		{name: "an attribute of another element", fsys: withSun(svg("sun", `<path d="M1 1" r="4" />`)), icon: "sun"},
		{name: "a namespaced attribute", fsys: withSun(svg("sun", `<path xmlns:x="urn:x" x:d="M1 1" />`)), icon: "sun"},
		{name: "a nested element", fsys: withSun(svg("sun", `<path d="M1 1"><path d="M2 2" /></path>`)), icon: "sun"},
		{name: "text", fsys: withSun(svg("sun", `hello`)), icon: "sun"},
		{name: "a value outside the characters SVG geometry needs", fsys: withSun(svg("sun", `<path d="M1 1&quot;&gt;" />`)), icon: "sun"},
		{name: "a processing instruction", fsys: withSun(`<?xml version="1.0"?>` + svg("sun", `<path d="M1 1" />`)), icon: "sun"},
		{name: "another namespace", fsys: withSun(strings.Replace(svg("sun", `<path d="M1 1" />`), "http://www.w3.org/2000/svg", "urn:not-svg", 1)), icon: "sun"},
		{name: "a second element after the svg", fsys: withSun(svg("sun", `<path d="M1 1" />`) + `<svg xmlns="http://www.w3.org/2000/svg"></svg>`), icon: "sun"},
		{name: "a missing icon", fsys: pkg(licence, nil), icon: "sun"},
		{name: "a name no Go function can take", fsys: withSun(svg("sun", `<path d="M1 1" />`)), icon: "Sun_2"},
		{name: "a licence that is not ISC", fsys: pkg(strings.Replace(licence, "ISC License", "MIT License", 1), map[string]string{"sun": svg("sun", `<path d="M1 1" />`)}), icon: "sun"},
		{
			name: "a derived icon without the MIT licence",
			fsys: pkg(licence[:strings.Index(licence, "The MIT License")], map[string]string{"moon": svg("moon", `<path d="M1 1" />`)}),
			icon: "moon",
		},
		{name: "no licence", fsys: fstest.MapFS{"icons/sun.svg": {Data: []byte(svg("sun", `<path d="M1 1" />`))}}, icon: "sun"},
		// The licence is held to lucide-static's layout, line for line: a
		// line reworded, added or missing could change which icon comes
		// under which licence, unseen.
		{name: "the Feather line reworded", fsys: withLicence(strings.Replace(licence, "Feather project:", "Feather project (MIT):", 1)), icon: "moon"},
		{name: "a line added after the ISC License", fsys: withLicence(iscPart + "Some icons are also under CC-BY-4.0.\n" + mitPart), icon: "sun"},
		{name: "a line added at the end", fsys: withLicence(licence + "\nExcept the icons in the extras folder.\n"), icon: "sun"},
		{name: "the ISC text reworded", fsys: withLicence(strings.Replace(licence, "for any\npurpose", "for some\npurpose", 1)), icon: "sun"},
		{name: "the MIT text reworded", fsys: withLicence(strings.Replace(licence, "free of charge", "for a fee", 1)), icon: "moon"},
		{name: "a second ISC copyright line", fsys: withLicence(strings.Replace(licence, "Contributors\n", "Contributors\nCopyright (c) 2026 Someone Else\n", 1)), icon: "sun"},
		{name: "no ISC copyright line", fsys: withLicence(strings.Replace(licence, "Copyright (c) 2026 Example Icons and Contributors\n", "", 1)), icon: "sun"},
		{
			name: "an MIT License with no list of the icons it covers",
			fsys: withLicence(strings.Replace(licence, "The following Lucide icons are derived from the Feather project:\n\nairplay, moon, x\n", "", 1)),
			icon: "sun",
		},
		{name: "a list of icons spelt otherwise", fsys: withLicence(strings.Replace(licence, "airplay, moon, x", "airplay; moon; x", 1)), icon: "moon"},
		{name: "a list with no MIT License after it", fsys: withLicence(licence[:strings.Index(licence, "The MIT License")]), icon: "sun"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()

			out, err := icongen.Render(t.Context(), tt.fsys, []string{tt.icon})
			if err == nil {
				t.Fatalf("render accepted it and wrote:\n%s", out)
			}
			if out != nil {
				t.Errorf("render returned %d bytes with its error", len(out))
			}
		})
	}
}

func TestRenderStopsWhenCancelled(t *testing.T) {
	t.Parallel()

	ctx, cancel := context.WithCancel(t.Context())
	cancel()
	if _, err := icongen.Render(ctx, fixture(), []string{"sun"}); !errors.Is(err, context.Canceled) {
		t.Errorf("render with a cancelled context = %v, want context.Canceled", err)
	}
}

func TestGenerateWritesTheFile(t *testing.T) {
	t.Parallel()

	out := filepath.Join(t.TempDir(), "icons.go")
	if err := icongen.Generate(t.Context(), fixture(), []string{"sun"}, out); err != nil {
		t.Fatalf("generate: %v", err)
	}
	dir, err := os.OpenRoot(filepath.Dir(out))
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() {
		if err := dir.Close(); err != nil {
			t.Error(err)
		}
	})
	got, err := dir.ReadFile(filepath.Base(out))
	if err != nil {
		t.Fatal(err)
	}
	want, err := icongen.Render(t.Context(), fixture(), []string{"sun"})
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(got, want) {
		t.Errorf("generate wrote\n%s\nwant render's\n%s", got, want)
	}
}

func TestTheCommittedList(t *testing.T) {
	t.Parallel()

	if got := strings.Join(icongen.Icons(), " "); got != "monitor moon sun" {
		t.Errorf("Icons() = %s, want the committed list: monitor moon sun", got)
	}
}
